    # Helper function to find the longest palindromic subsequence
    def longest_palindromic_subsequence(string, memo={}):
        if len(string) <= 1:
            return len(string)
        if string in memo:
            return memo[string]
        if string[0] == string[-1]:
            memo[string] = longest_palindromic_subsequence(string[1:-1], memo) + 2
        else:
            memo[string] = max(longest_palindromic_subsequence(string[1:], memo),
                               longest_palindromic_subsequence(string[:-1], memo))
        return memo[string]

    return longest_palindromic_subsequence(s)

